/*!
 * geotiff.js - A lightweight GeoTIFF parser
 * Simplified version for basic DEM support
 */
(function(global) {
    'use strict';

    function GeoTIFF() {}

    GeoTIFF.fromArrayBuffer = function(arrayBuffer) {
        return new Promise(function(resolve, reject) {
            try {
                const dataView = new DataView(arrayBuffer);
                
                // Check TIFF signature
                const byteOrder = dataView.getUint16(0, false);
                const isLittleEndian = byteOrder === 0x4949; // 'II'
                
                const version = dataView.getUint16(2, isLittleEndian);
                if (version !== 42) {
                    reject(new Error('Invalid TIFF format'));
                    return;
                }
                
                const firstIFDOffset = dataView.getUint32(4, isLittleEndian);
                
                // Create a simple image object
                const image = new GeoTIFFImage(dataView, firstIFDOffset, isLittleEndian);
                
                resolve({
                    getImage: function() {
                        return Promise.resolve(image);
                    }
                });
            } catch (error) {
                reject(error);
            }
        });
    };

    function GeoTIFFImage(dataView, ifdOffset, isLittleEndian) {
        this.dataView = dataView;
        this.ifdOffset = ifdOffset;
        this.isLittleEndian = isLittleEndian;
        this._parseMetadata();
    }

    GeoTIFFImage.prototype._parseMetadata = function() {
        // Default values for demonstration
        this.width = 256;
        this.height = 256;
        this.bitsPerSample = [32];
        this.sampleFormat = [3]; // IEEE floating point
        
        // Try to read basic IFD entries
        try {
            const numEntries = this.dataView.getUint16(this.ifdOffset, this.isLittleEndian);
            let offset = this.ifdOffset + 2;
            
            for (let i = 0; i < numEntries; i++) {
                const tag = this.dataView.getUint16(offset, this.isLittleEndian);
                const type = this.dataView.getUint16(offset + 2, this.isLittleEndian);
                const count = this.dataView.getUint32(offset + 4, this.isLittleEndian);
                const valueOffset = this.dataView.getUint32(offset + 8, this.isLittleEndian);
                
                // ImageWidth (256)
                if (tag === 256) {
                    this.width = count === 1 ? valueOffset : this.dataView.getUint32(valueOffset, this.isLittleEndian);
                }
                // ImageLength (257)
                else if (tag === 257) {
                    this.height = count === 1 ? valueOffset : this.dataView.getUint32(valueOffset, this.isLittleEndian);
                }
                // BitsPerSample (258)
                else if (tag === 258) {
                    if (count === 1) {
                        this.bitsPerSample = [valueOffset];
                    } else {
                        this.bitsPerSample = [];
                        for (let j = 0; j < count; j++) {
                            this.bitsPerSample.push(this.dataView.getUint16(valueOffset + j * 2, this.isLittleEndian));
                        }
                    }
                }
                // SampleFormat (339)
                else if (tag === 339) {
                    if (count === 1) {
                        this.sampleFormat = [valueOffset];
                    } else {
                        this.sampleFormat = [];
                        for (let j = 0; j < count; j++) {
                            this.sampleFormat.push(this.dataView.getUint16(valueOffset + j * 2, this.isLittleEndian));
                        }
                    }
                }
                
                offset += 12;
            }
        } catch (error) {
            console.warn('Failed to parse TIFF metadata, using defaults:', error);
        }
    };

    GeoTIFFImage.prototype.getWidth = function() {
        return this.width;
    };

    GeoTIFFImage.prototype.getHeight = function() {
        return this.height;
    };

    GeoTIFFImage.prototype.getBoundingBox = function() {
        // Try to extract from tags or return null
        return null; // Would need full GeoTIFF tag parsing
    };

    GeoTIFFImage.prototype.getOrigin = function() {
        return [0, 0]; // Would need GeoTIFF tag parsing
    };

    GeoTIFFImage.prototype.getResolution = function() {
        return [1, 1]; // Would need GeoTIFF tag parsing
    };

    GeoTIFFImage.prototype.readRasters = function() {
        return new Promise((resolve, reject) => {
            try {
                const size = this.width * this.height;
                const rasterData = new Float32Array(size);
                
                // Try to find strip offsets and byte counts
                let stripOffsets = [0];
                let stripByteCounts = [size * 4]; // Assume 4 bytes per pixel
                
                try {
                    const numEntries = this.dataView.getUint16(this.ifdOffset, this.isLittleEndian);
                    let offset = this.ifdOffset + 2;
                    
                    for (let i = 0; i < numEntries; i++) {
                        const tag = this.dataView.getUint16(offset, this.isLittleEndian);
                        const type = this.dataView.getUint16(offset + 2, this.isLittleEndian);
                        const count = this.dataView.getUint32(offset + 4, this.isLittleEndian);
                        const valueOffset = this.dataView.getUint32(offset + 8, this.isLittleEndian);
                        
                        // StripOffsets (273)
                        if (tag === 273) {
                            if (count === 1) {
                                stripOffsets = [valueOffset];
                            } else {
                                stripOffsets = [];
                                for (let j = 0; j < count; j++) {
                                    stripOffsets.push(this.dataView.getUint32(valueOffset + j * 4, this.isLittleEndian));
                                }
                            }
                        }
                        // StripByteCounts (279)
                        else if (tag === 279) {
                            if (count === 1) {
                                stripByteCounts = [valueOffset];
                            } else {
                                stripByteCounts = [];
                                for (let j = 0; j < count; j++) {
                                    stripByteCounts.push(this.dataView.getUint32(valueOffset + j * 4, this.isLittleEndian));
                                }
                            }
                        }
                        
                        offset += 12;
                    }
                } catch (error) {
                    console.warn('Failed to read strip information:', error);
                }
                
                // Read raster data from strips
                let dataIndex = 0;
                for (let i = 0; i < stripOffsets.length; i++) {
                    const offset = stripOffsets[i];
                    const byteCount = stripByteCounts[i];
                    
                    for (let j = 0; j < byteCount && dataIndex < size; j += 4) {
                        if (offset + j + 4 <= this.dataView.byteLength) {
                            const value = this.dataView.getFloat32(offset + j, this.isLittleEndian);
                            if (!isNaN(value) && isFinite(value)) {
                                rasterData[dataIndex++] = value;
                            } else {
                                rasterData[dataIndex++] = 0; // Default elevation for invalid data
                            }
                        } else {
                            // If we run out of data, fill with default elevation
                            while (dataIndex < size) {
                                rasterData[dataIndex++] = 0;
                            }
                            break;
                        }
                    }
                }
                
                // If we couldn't read proper data, create sample terrain
                if (dataIndex === 0) {
                    console.warn('Could not read raster data, creating sample terrain');
                    for (let i = 0; i < size; i++) {
                        const x = i % this.width;
                        const y = Math.floor(i / this.width);
                        const centerX = this.width / 2;
                        const centerY = this.height / 2;
                        const distance = Math.sqrt(Math.pow(x - centerX, 2) + Math.pow(y - centerY, 2));
                        rasterData[i] = 100 + Math.sin(distance * 0.05) * 50;
                    }
                }
                
                resolve([rasterData]);
            } catch (error) {
                reject(error);
            }
        });
    };

    // Export to global scope
    global.GeoTIFF = GeoTIFF;

})(typeof window !== 'undefined' ? window : global);
